update_md5_d93814aea1e4c8d628bc868ff220a.content_md5_d93814aea1e4c8d628bc868ff220:
import path from "path"
import { fileURLToPath } from "url"

type LoadedWasmAsset = {
  bytes: ArrayBuffer | null
  path: string | null
  tried: string[]
}

function unique(values: string[]) {
  return [...new Set(values.filter(Boolean).map((value) => path.normalize(value)))]
}

function rootCandidates() {
  const execDir = path.dirname(process.execPath)
  const sourceRoot = fileURLToPath(new URL("../../../wasm/core/pkg/", import.meta.url))
  return unique([
    process.env.OPENCODE_WASM_ROOT ?? "",
    path.resolve(execDir, "../wasm/core/pkg"),
    path.resolve(execDir, "../../wasm/core/pkg"),
    path.resolve(execDir, "../../../wasm/core/pkg"),
    path.resolve(process.cwd(), "wasm/core/pkg"),
    path.resolve(process.cwd(), "../wasm/core/pkg"),
    path.resolve(process.cwd(), "../../wasm/core/pkg"),
    path.resolve(process.cwd(), "packages/wasm/core/pkg"),
    path.resolve(process.cwd(), "../packages/wasm/core/pkg"),
    path.resolve(process.cwd(), "../../packages/wasm/core/pkg"),
    sourceRoot,
  ])
}

export function wasmAssetCandidates(relativePath: string) {
  const normalized = relativePath.replaceAll("\\", "/").replace(/^\/+/, "")
  return rootCandidates().map((root) => path.resolve(root, normalized))
}

export async function readWasmAsset(relativePath: string): Promise<LoadedWasmAsset> {
  const tried = wasmAssetCandidates(relativePath)
  for (const candidate of tried) {
    const file = Bun.file(candidate)
    if (!(await file.exists())) continue
    return { bytes: await file.arrayBuffer(), path: candidate, tried }
  }
  return { bytes: null, path: null, tried }
}

export * as WasmPath from "./wasm-path"

update_md5_f0ff2ea95258948ffd20568a8fa21.find_text:
const baseDir = dirname(process.execPath)
const paths = [
  resolve(baseDir, "../wasm/core/pkg/diffy/diffy_wasm_bg.wasm"),
  resolve(baseDir, "../../wasm/core/pkg/diffy/diffy_wasm_bg.wasm"),
  resolve(baseDir, "../../../wasm/core/pkg/diffy/diffy_wasm_bg.wasm"),
]
let bytes: ArrayBuffer | null = null
let loadedPath = ""
for (const p of paths) {
  try {
    const file = Bun.file(p)
    bytes = await file.arrayBuffer()
    loadedPath = p
    break
  } catch { /* try next */ }
}
if (!bytes) { Log.Default.warn("diff-wasm: no WASM file found, tried: " + JSON.stringify(paths)); return null }
Log.Default.warn("diff-wasm: loaded WASM from " + loadedPath)

